// Package tsurara is the runtime library for Go code generated by tsurara (design.md 18.9,
// docs/languages/go.md).
//
// Generated functions pass an OperationDef and an Input to Do, which builds the request, sends it
// through a Transport (net/http by default), and returns (*Success[T], error). Every error it
// returns is a *Failure[E] whose Kind is one of the contract's result kinds.
package tsurara

import (
	"bytes"
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math/rand/v2"
	"net/http"
	"slices"
	"strconv"
	"strings"
	"time"
)

// File is a binary value with an optional file name and media type. It is sent as a binary body or
// a multipart file part; in JSON it is base64, as []byte.
type File struct {
	Content     []byte
	Filename    string
	ContentType string
}

func (f File) MarshalJSON() ([]byte, error) { return json.Marshal(f.Content) }

func (f *File) UnmarshalJSON(data []byte) error { return json.Unmarshal(data, &f.Content) }

// Part is one multipart part: a file, or a value serialized by the part's encoding.
type Part struct {
	Name  string
	Value any
	File  *File
}

// Body is a request body: a value that the media type serializes, a file, or multipart parts.
type Body struct {
	Value any
	File  *File
	Parts []Part
}

// Input is what a call sends. Generated functions fill it with its methods (encode.go).
type Input struct {
	Path        []Member
	Query       []Member
	Headers     []Member
	Cookies     []Member
	QueryString any
	HasQS       bool
	Body        *Body
	// ContentType is the request media type, for operations with several.
	ContentType string
	// Timeout overrides the client's timeout.
	Timeout time.Duration
	// EncodeError is why a value could not be encoded; the call then fails with KindUnexpected
	// without sending anything.
	EncodeError error
}

// PayloadKind says what a Payload holds.
type PayloadKind int

const (
	PayloadNone PayloadKind = iota
	PayloadJSON
	PayloadText
	PayloadBytes
)

// Payload is a response body as read by parseAs.
type Payload struct {
	Kind PayloadKind
	// JSON is the raw JSON of a PayloadJSON.
	JSON        []byte
	Text        string
	Bytes       []byte
	ContentType string
	// stream is a body kept open to read item by item (DoItems).
	stream *stream
}

// Value is the payload as an ordered JSON value: text is a string, bytes base64 (as []byte), no
// body nil.
func (p Payload) Value() any {
	switch p.Kind {
	case PayloadJSON:
		v, _ := ParseValue(p.JSON)
		return v
	case PayloadText:
		return p.Text
	case PayloadBytes:
		return base64.StdEncoding.EncodeToString(p.Bytes)
	}
	return nil
}

// Success is a response with a success status of the definition.
type Success[T any] struct {
	Status    int
	Data      T
	Headers   http.Header
	Operation OperationInfo
}

// Kind is one of the contract's result kinds (spec/README.md).
type Kind string

const (
	KindSuccess    Kind = "success"
	KindHTTP       Kind = "http"
	KindNetwork    Kind = "network"
	KindTimeout    Kind = "timeout"
	KindParse      Kind = "parse"
	KindUnexpected Kind = "unexpected"
	KindAborted    Kind = "aborted"
)

// Failure is every outcome but a success. E is the documented error body type of the operation.
type Failure[E any] struct {
	Kind Kind
	// Status is the HTTP status, for KindHTTP and KindParse.
	Status int
	// Documented reports that Status is documented; Body then holds its body.
	Documented bool
	Body       E
	// Raw is the body of an undocumented status.
	Raw         Payload
	Headers     http.Header
	ContentType string
	Cause       error
	Operation   OperationInfo
}

func (f *Failure[E]) Error() string {
	switch f.Kind {
	case KindHTTP:
		return fmt.Sprintf("tsurara: %s failed with HTTP %d", f.Operation.ID, f.Status)
	case KindTimeout:
		return fmt.Sprintf("tsurara: %s failed with timeout", f.Operation.ID)
	}
	return fmt.Sprintf("tsurara: %s failed with %s: %v", f.Operation.ID, f.Kind, f.Cause)
}

// FailureInfo is what every failure has, whatever its documented error body type.
type FailureInfo struct {
	Kind        Kind
	Status      int
	Documented  bool
	Headers     http.Header
	ContentType string
	Cause       error
	Operation   OperationInfo
}

// AnyFailure is a *Failure[E] of any E: one errors.As reads the failures of every operation.
//
//	var f tsurara.AnyFailure
//	if errors.As(err, &f) && f.Info().Kind == tsurara.KindHTTP { ... }
type AnyFailure interface {
	error
	Info() FailureInfo
}

// Info returns the fields that do not depend on E.
func (f *Failure[E]) Info() FailureInfo {
	return FailureInfo{
		Kind: f.Kind, Status: f.Status, Documented: f.Documented, Headers: f.Headers,
		ContentType: f.ContentType, Cause: f.Cause, Operation: f.Operation,
	}
}

// Unwrap returns the cause: context.Canceled for KindAborted, the transport's error for
// KindNetwork.
func (f *Failure[E]) Unwrap() error { return f.Cause }

// Request is a request as the transport sends it.
type Request struct {
	Method string
	URL    string
	// Header names are lower case.
	Header http.Header
	Body   []byte
}

// Response is a response as the transport returns it.
type Response struct {
	Status int
	Header http.Header
	Body   []byte
}

// Transport sends requests. The default sends them with an *http.Client.
type Transport interface {
	Send(ctx context.Context, r *Request) (*Response, error)
}

// StreamResponse is a response whose headers have arrived and whose body is read as it comes.
type StreamResponse struct {
	Status int
	Header http.Header
	Body   io.ReadCloser
}

// StreamTransport is a Transport that returns once the headers have arrived, so that responses
// read item by item (DoItems) arrive as the server writes them. The client sends every request with
// SendStream when the transport has it; HTTPTransport does. The body is read while ctx is alive.
type StreamTransport interface {
	Transport
	SendStream(ctx context.Context, r *Request) (*StreamResponse, error)
}

// HTTPTransport sends requests with an *http.Client. When Client is nil, it uses one that follows
// redirects within the origin of the request only: a redirect to another origin is not followed, and
// its response is the result, so that headers such as API keys never reach another host.
type HTTPTransport struct {
	Client *http.Client
}

var sameOriginClient = &http.Client{CheckRedirect: func(req *http.Request, via []*http.Request) error {
	if len(via) >= 10 {
		return errors.New("stopped after 10 redirects")
	}
	first := via[0].URL
	if !strings.EqualFold(req.URL.Scheme, first.Scheme) || !strings.EqualFold(req.URL.Host, first.Host) {
		return http.ErrUseLastResponse
	}
	return nil
}}

func (t HTTPTransport) Send(ctx context.Context, r *Request) (*Response, error) {
	resp, err := t.SendStream(ctx, r)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	return &Response{Status: resp.Status, Header: resp.Header, Body: body}, nil
}

func (t HTTPTransport) SendStream(ctx context.Context, r *Request) (*StreamResponse, error) {
	req, err := http.NewRequestWithContext(ctx, r.Method, r.URL, bytes.NewReader(r.Body))
	if err != nil {
		return nil, err
	}
	for k, vs := range r.Header {
		for _, v := range vs {
			req.Header.Add(k, v)
		}
	}
	client := t.Client
	if client == nil {
		client = sameOriginClient
	}
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	return &StreamResponse{Status: resp.StatusCode, Header: resp.Header, Body: resp.Body}, nil
}

// sendStream sends with SendStream, or with Send and the whole body when the transport has no
// SendStream.
func sendStream(ctx context.Context, t Transport, r *Request) (*StreamResponse, error) {
	if st, ok := t.(StreamTransport); ok {
		return st.SendStream(ctx, r)
	}
	resp, err := t.Send(ctx, r)
	if err != nil {
		return nil, err
	}
	return &StreamResponse{Status: resp.Status, Header: resp.Header, Body: io.NopCloser(bytes.NewReader(resp.Body))}, nil
}

// Retry options (design.md 8.4). DefaultRetry retries idempotent methods after network failures
// and 408, 429, 500, 502, 503 and 504, up to 2 times; the wait is Retry-After when the response
// has it, otherwise exponential backoff with full jitter, capped by MaxDelay. Timeouts are not
// retried, and a wait that would end after the deadline is not started.
type Retry struct {
	Max       int
	Methods   []string
	Statuses  []int
	BaseDelay time.Duration
	MaxDelay  time.Duration
}

// DefaultRetry returns the retry options every runtime uses by default.
func DefaultRetry() Retry {
	return Retry{
		Max:       2,
		Methods:   []string{"GET", "HEAD", "OPTIONS", "PUT", "DELETE"},
		Statuses:  []int{408, 429, 500, 502, 503, 504},
		BaseDelay: 100 * time.Millisecond,
		MaxDelay:  30 * time.Second,
	}
}

func (r Retry) retries(method string) int {
	for _, m := range r.Methods {
		if strings.EqualFold(m, method) {
			return r.Max
		}
	}
	return 0
}

// Delay is the wait before retry number attempt (from 1).
func (r Retry) Delay(attempt int, response *Response) time.Duration {
	if response != nil {
		if after, ok := RetryAfter(response.Header, time.Now()); ok {
			return min(after, r.MaxDelay)
		}
	}
	ceiling := r.BaseDelay << (attempt - 1)
	if ceiling > r.MaxDelay || ceiling <= 0 {
		ceiling = r.MaxDelay
	}
	return time.Duration(rand.Float64() * float64(ceiling))
}

// RetryAfter reads Retry-After: seconds or an HTTP date.
func RetryAfter(h http.Header, now time.Time) (time.Duration, bool) {
	value := strings.TrimSpace(h.Get("Retry-After"))
	if value == "" {
		return 0, false
	}
	if s, err := strconv.ParseUint(value, 10, 63); err == nil {
		return time.Duration(s) * time.Second, true
	}
	at, err := http.ParseTime(value)
	if err != nil {
		return 0, false
	}
	return max(at.Sub(now), 0), true
}

// AuthFunc returns the credential for a security scheme of an operation, or false.
type AuthFunc func(scheme SecurityUse, op OperationInfo) (string, bool)

// Client sends the requests of generated functions. Create it with NewClient; it is safe for
// concurrent use.
type Client struct {
	baseURL              string
	transport            Transport
	headers              http.Header
	timeout              time.Duration
	retry                *Retry
	auth                 AuthFunc
	onUndocumentedStatus func(op OperationInfo, status int)
	onResult             func(op OperationInfo, kind Kind)
}

// Option configures a Client.
type Option func(*Client)

// WithTransport sends with another Transport (tests, other HTTP stacks).
func WithTransport(t Transport) Option { return func(c *Client) { c.transport = t } }

// WithHTTPClient sends with this *http.Client.
func WithHTTPClient(h *http.Client) Option {
	return func(c *Client) { c.transport = HTTPTransport{Client: h} }
}

// WithHeader adds a header to every request.
func WithHeader(name, value string) Option {
	return func(c *Client) { c.headers.Add(name, value) }
}

// WithTimeout limits every call, over all of its attempts.
func WithTimeout(d time.Duration) Option { return func(c *Client) { c.timeout = d } }

// WithRetry retries as r says.
func WithRetry(r Retry) Option { return func(c *Client) { c.retry = &r } }

// WithAuth gives credentials for the operations' security schemes (spec/README.md,
// Authentication).
func WithAuth(f AuthFunc) Option { return func(c *Client) { c.auth = f } }

// OnUndocumentedStatus is told about every response whose status the definition does not
// document.
func OnUndocumentedStatus(f func(op OperationInfo, status int)) Option {
	return func(c *Client) { c.onUndocumentedStatus = f }
}

// OnResult observes every outcome by its kind.
func OnResult(f func(op OperationInfo, kind Kind)) Option {
	return func(c *Client) { c.onResult = f }
}

// NewClient returns a client for the API at baseURL.
func NewClient(baseURL string, opts ...Option) *Client {
	c := &Client{
		baseURL:   strings.TrimRight(baseURL, "/"),
		transport: HTTPTransport{},
		headers:   http.Header{},
	}
	for _, o := range opts {
		o(c)
	}
	return c
}

// Do runs an operation and decodes the success body into S and a documented error body into E.
func Do[S, E any](ctx context.Context, c *Client, def *OperationDef, in *Input) (*Success[S], error) {
	raw, failure := c.DoRaw(ctx, def, in)
	if failure != nil {
		return nil, typedFailure[E](failure)
	}
	data, err := decodePayload[S](raw.Data)
	if err != nil {
		return nil, &Failure[E]{
			Kind: KindParse, Status: raw.Status, Headers: raw.Headers,
			ContentType: raw.Headers.Get("Content-Type"), Cause: err, Operation: raw.Operation,
		}
	}
	return &Success[S]{Status: raw.Status, Data: data, Headers: raw.Headers, Operation: raw.Operation}, nil
}

// DoItems runs an operation whose success is read item by item (Server-Sent Events, JSON Lines,
// JSON text sequences; design.md 8.5) and decodes each item into T and a documented error body into
// E. It returns once the headers have arrived; the client's timeout does not cover reading the
// items, and ctx does: cancelling it ends the stream.
func DoItems[T, E any](ctx context.Context, c *Client, def *OperationDef, in *Input) (*Success[*Items[T]], error) {
	raw, failure := c.do(ctx, def, in, true)
	if failure != nil {
		return nil, typedFailure[E](failure)
	}
	if raw.Data.stream == nil {
		return nil, &Failure[E]{
			Kind: KindParse, Status: raw.Status, Headers: raw.Headers,
			ContentType: raw.Headers.Get("Content-Type"), Cause: errors.New("tsurara: the response is not read item by item"),
			Operation: raw.Operation,
		}
	}
	return &Success[*Items[T]]{Status: raw.Status, Data: &Items[T]{s: raw.Data.stream}, Headers: raw.Headers, Operation: raw.Operation}, nil
}

// typedFailure decodes the documented body of a failure into E.
func typedFailure[E any](failure *Failure[Payload]) *Failure[E] {
	out := &Failure[E]{
		Kind: failure.Kind, Status: failure.Status, Headers: failure.Headers,
		ContentType: failure.ContentType, Cause: failure.Cause, Operation: failure.Operation,
		Raw: failure.Raw,
	}
	if failure.Documented {
		body, err := decodePayload[E](failure.Body)
		if err != nil {
			out.Kind = KindParse
			out.Cause = err
			return out
		}
		out.Documented = true
		out.Body = body
	}
	return out
}

// decodePayload reads a payload into T: JSON through encoding/json, text into a string, bytes into
// []byte, and anything into any.
func decodePayload[T any](p Payload) (T, error) {
	var v T
	switch p.Kind {
	case PayloadNone:
		return v, nil
	case PayloadJSON:
		if a, ok := any(&v).(*any); ok {
			*a = p.Value()
			return v, nil
		}
		err := json.Unmarshal(p.JSON, &v)
		return v, err
	case PayloadText:
		switch t := any(&v).(type) {
		case *string:
			*t = p.Text
			return v, nil
		case *any:
			*t = p.Text
			return v, nil
		}
		err := json.Unmarshal([]byte(JSONText(p.Text)), &v)
		return v, err
	default:
		switch t := any(&v).(type) {
		case *[]byte:
			*t = p.Bytes
			return v, nil
		case *any:
			*t = p.Bytes
			return v, nil
		case *File:
			*t = File{Content: p.Bytes, ContentType: p.ContentType}
			return v, nil
		}
		return v, fmt.Errorf("a binary body cannot be read as %T", v)
	}
}

// DoRaw runs an operation and returns the bodies as payloads. Bodies read item by item are read
// whole as bytes.
func (c *Client) DoRaw(ctx context.Context, def *OperationDef, in *Input) (*Success[Payload], *Failure[Payload]) {
	return c.do(ctx, def, in, false)
}

func (c *Client) do(ctx context.Context, def *OperationDef, in *Input, items bool) (*Success[Payload], *Failure[Payload]) {
	op := def.info()
	if in == nil {
		in = &Input{}
	}
	s, f := c.run(ctx, def, op, in, items)
	if c.onResult != nil {
		kind := KindSuccess
		if f != nil {
			kind = f.Kind
		}
		c.onResult(op, kind)
	}
	return s, f
}

func (c *Client) run(ctx context.Context, def *OperationDef, op OperationInfo, in *Input, items bool) (*Success[Payload], *Failure[Payload]) {
	unexpected := func(err error) *Failure[Payload] {
		return &Failure[Payload]{Kind: KindUnexpected, Cause: err, Operation: op}
	}
	if def.V != OperationDefVersion {
		return nil, unexpected(fmt.Errorf("tsurara: OperationDef version %d is not supported by this runtime (expected %d); regenerate the code or update the runtime", def.V, OperationDefVersion))
	}
	if in.EncodeError != nil {
		return nil, unexpected(fmt.Errorf("tsurara: a value could not be encoded: %w", in.EncodeError))
	}
	req, err := c.prepare(def, op, in)
	if err != nil {
		return nil, unexpected(err)
	}
	timeout := c.timeout
	if in.Timeout > 0 {
		timeout = in.Timeout
	}
	// The timeout covers sending, the headers and reading a whole body, but not a body read item by
	// item, so it cancels the request with a timer that stops once such a body starts.
	reqCtx, cancel := context.WithCancelCause(ctx)
	var deadline time.Time
	var timer *time.Timer
	if timeout > 0 {
		deadline = time.Now().Add(timeout)
		timer = time.AfterFunc(timeout, func() { cancel(context.DeadlineExceeded) })
	}
	release := func() {
		if timer != nil {
			timer.Stop()
		}
		cancel(nil)
	}
	transportFailure := func(err error) *Failure[Payload] {
		switch {
		case errors.Is(context.Cause(reqCtx), context.DeadlineExceeded) || errors.Is(err, context.DeadlineExceeded):
			return &Failure[Payload]{Kind: KindTimeout, Cause: context.DeadlineExceeded, Operation: op}
		case errors.Is(err, context.Canceled) || ctx.Err() != nil:
			cause := err
			if ctx.Err() != nil {
				cause = ctx.Err()
			}
			return &Failure[Payload]{Kind: KindAborted, Cause: cause, Operation: op}
		}
		return &Failure[Payload]{Kind: KindNetwork, Cause: err, Operation: op}
	}
	sr, err := c.send(reqCtx, req, deadline)
	if err != nil {
		release()
		return nil, transportFailure(err)
	}
	if sr.Header == nil {
		sr.Header = http.Header{}
	}
	if items {
		if kind, jsonEvents, ok := sequenceOf(def, sr); ok {
			if timer != nil {
				timer.Stop()
			}
			s := &Success[Payload]{Status: sr.Status, Headers: sr.Header, Operation: op, Data: Payload{
				ContentType: sr.Header.Get("Content-Type"),
				stream:      &stream{body: sr.Body, kind: kind, jsonEvents: jsonEvents, stop: func() { cancel(nil) }},
			}}
			return s, nil
		}
	}
	body, err := io.ReadAll(sr.Body)
	sr.Body.Close()
	release()
	if err != nil {
		return nil, transportFailure(err)
	}
	resp := &Response{Status: sr.Status, Header: sr.Header, Body: body}
	s, f := toResult(def, op, resp)
	if f != nil && f.Kind == KindHTTP && !f.Documented && c.onUndocumentedStatus != nil {
		c.onUndocumentedStatus(op, f.Status)
	}
	return s, f
}

func (c *Client) prepare(def *OperationDef, op OperationInfo, in *Input) (*Request, error) {
	params := def.Params
	path, err := expandPath(def.Path, in.Path, params.Path)
	if err != nil {
		return nil, err
	}
	var query string
	if params.QueryString != nil && in.HasQS {
		query = buildQueryString(in.QueryString, params.QueryString.ContentType)
	} else {
		query = buildQuery(in.Query, params.Query)
	}
	header := http.Header{}
	for k, vs := range c.headers {
		header[strings.ToLower(k)] = slices.Clone(vs)
	}
	set := func(name, value string) { header[strings.ToLower(name)] = []string{value} }
	for _, m := range in.Headers {
		if s, ok := m.Value.(string); ok {
			set(m.Key, s)
			continue
		}
		d, _ := params.Headers.Get(m.Key)
		set(m.Key, serializeHeaderParam(m.Value, d))
	}
	cookie := buildCookie(in.Cookies, params.Cookies)
	// Authentication: the first alternative with every credential.
	if c.auth != nil {
	alternatives:
		for _, alternative := range def.Security {
			var schemes []SecurityUse
			var values []string
			for _, s := range alternative {
				if s.Type == "mutualTLS" {
					continue
				}
				v, ok := c.auth(s, op)
				if !ok {
					continue alternatives
				}
				schemes = append(schemes, s)
				values = append(values, v)
			}
			for i, s := range schemes {
				place(s, values[i], set, &query, &cookie)
			}
			break
		}
	}
	if cookie != "" {
		set("cookie", cookie)
	}
	var body []byte
	if in.Body != nil && def.Body != nil {
		enc, err := encodeBody(in.Body, def.Body, in.ContentType)
		if err != nil {
			return nil, err
		}
		body = enc.content
		if enc.contentType != "" {
			set("content-type", enc.contentType)
		}
	}
	url := c.baseURL + path
	if query != "" {
		if strings.Contains(url, "?") {
			url += "&" + query
		} else {
			url += "?" + query
		}
	}
	return &Request{Method: strings.ToUpper(def.Method), URL: url, Header: header, Body: body}, nil
}

func place(s SecurityUse, value string, set func(string, string), query, cookie *string) {
	push := func(target *string, part, sep string) {
		if *target != "" {
			*target += sep
		}
		*target += part
	}
	if s.Type == "apiKey" {
		name := s.Name
		if name == "" {
			name = s.Scheme
		}
		switch s.In {
		case "query":
			push(query, component(name)+"="+component(value), "&")
		case "cookie":
			push(cookie, name+"="+component(value), "; ")
		default:
			set(name, value)
		}
		return
	}
	scheme := "bearer"
	if s.Type == "http" && s.HTTPScheme != "" {
		scheme = s.HTTPScheme
	}
	switch strings.ToLower(scheme) {
	case "basic":
		set("authorization", "Basic "+base64.StdEncoding.EncodeToString([]byte(value)))
	case "bearer":
		set("authorization", "Bearer "+value)
	default:
		set("authorization", scheme+" "+value)
	}
}

// send sends with retries when the client has them, and returns once the headers have arrived.
func (c *Client) send(ctx context.Context, req *Request, deadline time.Time) (*StreamResponse, error) {
	retries := 0
	if c.retry != nil {
		retries = c.retry.retries(req.Method)
	}
	for attempt := 0; ; attempt++ {
		resp, err := sendStream(ctx, c.transport, req)
		if ctx.Err() != nil {
			if resp != nil {
				resp.Body.Close()
			}
			return nil, ctx.Err()
		}
		if c.retry == nil || attempt >= retries {
			return resp, err
		}
		var wait time.Duration
		switch {
		case err != nil:
			wait = c.retry.Delay(attempt+1, nil)
		case slices.Contains(c.retry.Statuses, resp.Status):
			// Retry-After is in the headers; the body is not needed.
			wait = c.retry.Delay(attempt+1, &Response{Status: resp.Status, Header: resp.Header})
		default:
			return resp, nil
		}
		if !deadline.IsZero() && time.Now().Add(wait).After(deadline) {
			return resp, err
		}
		if resp != nil {
			resp.Body.Close()
		}
		timer := time.NewTimer(wait)
		select {
		case <-ctx.Done():
			timer.Stop()
			return nil, ctx.Err()
		case <-timer.C:
		}
	}
}

// sequenceOf says how a success response is read item by item, if its definition says so.
func sequenceOf(def *OperationDef, r *StreamResponse) (sequenceKind, json.RawMessage, bool) {
	key, entry, found := findResponse(def, r.Status)
	if !found || r.Status >= 400 || (key == "default" && hasSuccessEntry(def)) {
		return 0, nil, false
	}
	as := entry.ParseAs
	if specific, ok := entry.ContentTypes.Get(mediaTypeOf(r.Header.Get("Content-Type"))); ok {
		as = specific
	}
	switch as {
	case ParseEvents:
		return seqEvents, entry.JSONEvents, true
	case ParseJSONLines:
		return seqJSONLines, nil, true
	case ParseJSONSeq:
		return seqJSONSeq, nil, true
	}
	return 0, nil, false
}

func findResponse(def *OperationDef, status int) (string, ResponseDef, bool) {
	for _, k := range []string{strconv.Itoa(status), strconv.Itoa(status/100) + "XX", "default"} {
		if r, ok := def.Responses.Get(k); ok {
			return k, r, true
		}
	}
	return "", ResponseDef{}, false
}

func hasSuccessEntry(def *OperationDef) bool {
	for _, e := range def.Responses {
		k := strings.ToUpper(e.Key)
		if d, ok := strings.CutSuffix(k, "XX"); ok {
			if n, err := strconv.Atoi(d); err == nil && n < 4 {
				return true
			}
		} else if n, err := strconv.Atoi(k); err == nil && n < 400 {
			return true
		}
	}
	return false
}

func guess(r *Response) ParseAs {
	mt := mediaTypeOf(r.Header.Get("Content-Type"))
	switch {
	case r.Status == 204 || r.Status == 205 || r.Status == 304:
		return ParseNone
	case isJSONMedia(mt):
		return ParseJSON
	case strings.HasPrefix(mt, "text/") || mt == "":
		return ParseText
	}
	return ParseBlob
}

func read(r *Response, as ParseAs) (Payload, error) {
	ct := r.Header.Get("Content-Type")
	switch as {
	case ParseNone:
		return Payload{}, nil
	case ParseText:
		return Payload{Kind: PayloadText, Text: string(r.Body), ContentType: ct}, nil
	case ParseBlob, ParseStream, ParseEvents, ParseJSONLines, ParseJSONSeq:
		return Payload{Kind: PayloadBytes, Bytes: r.Body, ContentType: ct}, nil
	case ParseAuto:
		return read(r, guess(r))
	}
	mt := mediaTypeOf(ct)
	if mt != "" && !isJSONMedia(mt) {
		return Payload{}, fmt.Errorf("expected JSON but the response has Content-Type %s", mt)
	}
	if !json.Valid(r.Body) {
		return Payload{}, fmt.Errorf("the response body is not valid JSON")
	}
	return Payload{Kind: PayloadJSON, JSON: r.Body, ContentType: ct}, nil
}

func readUndocumented(r *Response) Payload {
	as := guess(r)
	if as == ParseJSON {
		if json.Valid(r.Body) {
			return Payload{Kind: PayloadJSON, JSON: r.Body, ContentType: r.Header.Get("Content-Type")}
		}
		as = ParseText
	}
	p, _ := read(r, as)
	return p
}

func toResult(def *OperationDef, op OperationInfo, r *Response) (*Success[Payload], *Failure[Payload]) {
	if r.Header == nil {
		r.Header = http.Header{}
	}
	status := r.Status
	key, entry, found := findResponse(def, status)
	ct := r.Header.Get("Content-Type")
	mt := mediaTypeOf(ct)
	parse := func() (Payload, error) {
		as := entry.ParseAs
		if specific, ok := entry.ContentTypes.Get(mt); ok {
			as = specific
		}
		return read(r, as)
	}
	parseFailure := func(err error) *Failure[Payload] {
		return &Failure[Payload]{Kind: KindParse, Status: status, Headers: r.Header, ContentType: ct, Cause: err, Operation: op}
	}
	success := status < 400 && found && (key != "default" || !hasSuccessEntry(def))
	switch {
	case found && success:
		data, err := parse()
		if err != nil {
			return nil, parseFailure(err)
		}
		return &Success[Payload]{Status: status, Data: data, Headers: r.Header, Operation: op}, nil
	case found && status >= 400:
		data, err := parse()
		if err != nil {
			return nil, parseFailure(err)
		}
		return nil, &Failure[Payload]{Kind: KindHTTP, Status: status, Documented: true, Body: data, Headers: r.Header, ContentType: ct, Operation: op}
	}
	raw := readUndocumented(r)
	return nil, &Failure[Payload]{Kind: KindHTTP, Status: status, Raw: raw, Headers: r.Header, ContentType: ct, Operation: op}
}
